import assert from'node:assert/strict';import{mkdtemp,rm,readFile,writeFile}from'node:fs/promises';import{tmpdir}from'node:os';import path from'node:path';import{chromium}from'playwright';import{extract}from'../../engine/extract.mjs';import{generate}from'../../engine/generate.mjs';import{run}from'../../engine/pipeline.mjs';import{serveStatic}from'../../engine/static.mjs';
import{parseContent,YAML}from'../../scripts/source-project.mjs';
const origin='http://127.0.0.1:9426',routes=['/nested-components/','/nested-multiple/'],dir=await mkdtemp(path.join(tmpdir(),'installed-nested-'));let browser,server;const checks=[];
try{
 const pages=[];for(const route of routes){const r=await fetch(origin+route);assert.equal(r.status,200);const html=await r.text();assert.ok(html.includes('e-n-tabs'));assert.ok(html.includes('e-n-accordion'));pages.push({...extract(html,origin+route),styles:[]});}
 await generate({source:origin+'/',identity:{title:'Nested Components'},design:{},navigation:[],metrics:{},pages,media:[]},dir);await run(process.execPath,['scripts/build.mjs'],{cwd:dir,timeout:120000});const records=JSON.parse(await readFile(path.join(dir,'routes.json'),'utf8')),record=records.find(r=>r.route==='/nested-components/'),file=path.join(dir,'content',record.collection,record.slug+'.md'),parsed=parseContent(await readFile(file,'utf8'),file);assert.ok(parsed.body.includes('nested-tabs Details editable content.'),'hidden nested tab content is Markdown');assert.ok(parsed.body.includes('nested-accordion Details editable content.'),'closed nested accordion content is Markdown');await writeFile(file,'---\n'+YAML.stringify(parsed.meta)+'---\n'+parsed.body.replace('nested-tabs Details editable content.','Edited nested tab content.').replace('nested-accordion Details editable content.','Edited nested accordion content.'));await run(process.execPath,['scripts/build.mjs'],{cwd:dir,timeout:120000});server=await serveStatic(path.join(dir,'output'));browser=await chromium.launch({channel:'chrome'});
 for(const route of routes)for(const width of[1440,390])for(const[side,base]of[['source',origin],['export',server.url]]){
  const page=await browser.newPage({viewport:{width,height:1000}});await page.route('**/*',r=>['GET','HEAD'].includes(r.request().method())&&new URL(r.request().url()).origin===new URL(base).origin?r.continue():r.abort());await page.addInitScript(()=>{window.detailsAnimations=[];const original=Element.prototype.animate;Element.prototype.animate=function(frames,options){if(this.matches('details'))window.detailsAnimations.push({duration:options.duration,height:frames.height});return original.call(this,frames,options);};});await page.goto(base+route,{waitUntil:'networkidle'});
  const tabs=page.locator('.e-n-tabs'),titles=tabs.locator('.e-n-tab-title'),panels=tabs.locator('[role=tabpanel]');await titles.nth(1).click();await page.waitForTimeout(450);assert.equal(await panels.nth(1).isVisible(),true);assert.equal(await panels.nth(0).isVisible(),false);
  const accordion=page.locator('.e-n-accordion'),items=accordion.locator(':scope > details'),summaries=accordion.locator(':scope > details > summary');assert.equal(await items.nth(0).evaluate(e=>e.open),true,side+' initial item');await page.evaluate(()=>{window.detailsAnimations=[];});await summaries.nth(1).click();await page.waitForTimeout(450);assert.equal(await items.nth(1).evaluate(e=>e.open),true);assert.equal(await items.nth(0).evaluate(e=>e.open),route==='/nested-multiple/',side+' '+route+' exclusive/multiple setting');
  const animations=await page.evaluate(()=>window.detailsAnimations);assert.ok(animations.some(a=>a.duration===400&&a.height[0]!==a.height[1]),side+' source-configured height transition');
  if(side==='export'&&route==='/nested-components/'){assert.ok((await panels.nth(1).innerText()).includes('Edited nested tab content.'));assert.ok((await items.nth(1).innerText()).includes('Edited nested accordion content.'));}
  checks.push({route,width,side,tabs:true,accordionMode:true,heightTransitionMs:400});await page.close();
 }
 console.log(JSON.stringify({plugin:'elementor',version:'4.3.5',checks,hiddenPanelMarkdownEdit:true,aiCalls:0,scope:'Installed nested tabs and accordion one/multiple modes; not complete plugin acceptance'}));
}finally{await browser?.close();await server?.close();await rm(dir,{recursive:true,force:true});}
